        let mut store = SettingsStore::new(cx, &default_settings());
        store.register_setting::<ItemSettings>();
        store.watch_settings_files(fs.clone(), cx, {
            let parse_results = parse_results.clone();
            move |_, result, _| {
                parse_results.borrow_mut().push(result);
